window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-6f257f695ecee51e"]={"versions": [{"id": "FIG-6f257f695ecee51e", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Sequenzdiagramm (Interaktionsdiagramm).\n</li><li><strong>Technischer Zweck:</strong> Spezifikation des Kontrollflusses zur Abfrage der aggregierten Belegungsgröße eines Datei-Containers (<code>FileStorage</code>) im Kontext der AUTOSAR Adaptive Platform (AP).\n</li><li><strong>Architektur-Kontext:</strong> Funktionaler Cluster <em>Persistency</em> (<code>ara::per</code>). Das Szenario demonstriert die Kapselung und Abstraktion des zugrundeliegenden Host-/POSIX-Dateisystems gegenüber der Anwendungsebene zwecks Einhaltung der Resource-Quota- und Sandbox-Grenzen.\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong><code>:Adaptive Application</code> (Akteur / Lifeline):</strong>\n<ul class=\"fig-list\"><li>Anwendungsinstanz/Prozess im User Space, agiert als Service-Consumer.\n</li></ul>\n</li><li><strong><code>«aapFunctionalCluster» :Persistency</code> (Architekturbaustein / Lifeline):</strong>\n<ul class=\"fig-list\"><li>Standardisierter AUTOSAR Adaptive Platform Functional Cluster (<code>ara::per</code>).\n</li><li>Kapselt Persistenzstrategien (Key-Value-Storage und File-Storage).\n</li><li>Bereitgestellte Schnittstelle: <code>ara::per::FileStorage::GetCurrentFileStorageSize()</code>.\n</li></ul>\n</li><li><strong><code>:Operating System</code> (Akteur / Lifeline):</strong>\n<ul class=\"fig-list\"><li>POSIX-konformes Betriebssystem (z. B. QNX Neutrino, Linux RT).\n</li><li>Verwaltet Virtual File System (VFS), Inodes und Blocktreiber.\n</li><li>Schnittstelle: Native OS-Systemaufrufe, im Diagramm abstrahiert als <code>getSize()</code>.\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Trigger:</strong> Die <code>:Adaptive Application</code> setzt den synchronen Aufruf <code>GetCurrentFileStorageSize()</code> auf einer geöffneten Instanz von <code>ara::per::FileStorage</code> ab.\n</li><li><strong>OS-Delegation:</strong> Der Cluster <code>:Persistency</code> initiiert intern den Aufruf <code>getSize()</code> an das <code>:Operating System</code>. Dies entspricht OS-seitig der Abfrage der physischen Dateigrößen bzw. Verzeichniseinträge (z. B. via <code>stat()</code> / <code>fstat()</code> / <code>statvfs()</code> oder Verzeichnistraversierung über <code>readdir()</code>).\n</li><li><strong>Ergebniserfassung &amp; Rückkehr:</strong>\n<ul class=\"fig-list\"><li>Das Betriebssystem liefert die File-Metadaten an <code>:Persistency</code> zurück.\n</li><li><code>:Persistency</code> aggregiert die Bytegrößen aller zugeordneten persistenten Dateien und terminiert die synchrone Ausführung mit Rückgabe des akkumulierten Werts als <code>ara::core::Result&lt;std::uint64_t&gt;</code>.\n</li><li>Tritt während des OS-Zugriffs ein Fehler auf (z. B. I/O-Fault, unvollständige Metadaten), bricht die Sequenz ab und transformiert den Fehler in einen <code>ara::per::PerErrc</code> (z. B. <code>kPhysicalStorageFailure</code>).\n</li></ul>\n</li></ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>API-Vertrag (Applikationsebene):</strong>\n<ul class=\"fig-list\"><li>Aufruf ist blockierend/synchron. Entwickler dürfen <code>GetCurrentFileStorageSize()</code> nicht in zeitkritischen Thread-Kontexten oder harten Echtzeitschleifen ausführen, da je nach Dateianzahl und Storage-Typ signifikante I/O-Latenzen entstehen.\n</li><li>Der Rückgabewert ist typisiert als <code>ara::core::Result&lt;std::uint64_t&gt;</code> und erzwingt zwingend eine Fehlerbehandlung vor dem Dereferenzieren des Werts.\n</li></ul>\n</li><li><strong>Platform- &amp; Stack-Implementierung:</strong>\n<ul class=\"fig-list\"><li>Der Persistency-Stack muss sicherstellen, dass nur Dateien erfasst werden, die zum Namespace und Scope des jeweiligen <code>PersistencyFileStorage</code> gehören (Vermeidung von Information Leakage).\n</li><li>Zur Latenzoptimierung empfiehlt sich stack-intern ein aggregiertes Tracking bei Schreiboperationen oder Caching der Dateigrößen, um wiederholte Traversierungen des VFS zu minimieren.\n</li></ul>\n</li><li><strong>Konfigurationsbezug (Manifeste):</strong>\n<ul class=\"fig-list\"><li>Die ermittelte Größe korreliert direkt mit dem im Execution/Platform-Manifest definierten Parameter <code>PersistencyFileStorage.maximumAllowedSize</code>.\n</li><li>Dient typischerweise dem präventiven Quota-Monitoring der Applikation, bevor Schreiboperationen via <code>OpenFileWrite()</code> oder <code>Write()</code> mit Quota-Exceeded-Fehlern fehlschlagen.\n</li></ul>\n</li></ul>"}, {"id": "FIG-aa102024e40b7d7b", "releases": ["R24-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Sequenzdiagramm (Interaktionsdiagramm).\n</li><li><strong>Technischer Zweck:</strong> Spezifikation des Kontrollflusses zur Abfrage der aggregierten Belegungsgröße eines Datei-Containers (<code>FileStorage</code>) im Kontext der AUTOSAR Adaptive Platform (AP).\n</li><li><strong>Architektur-Kontext:</strong> Funktionaler Cluster <em>Persistency</em> (<code>ara::per</code>). Das Szenario demonstriert die Kapselung und Abstraktion des zugrundeliegenden Host-/POSIX-Dateisystems gegenüber der Anwendungsebene zwecks Einhaltung der Resource-Quota- und Sandbox-Grenzen.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong><code>:Adaptive Application</code> (Akteur / Lifeline):</strong>\n<ul class=\"fig-list\"><li>Anwendungsinstanz/Prozess im User Space, agiert als Service-Consumer.\n</li></ul>\n</li><li><strong><code>«aapFunctionalCluster» :Persistency</code> (Architekturbaustein / Lifeline):</strong>\n<ul class=\"fig-list\"><li>Standardisierter AUTOSAR Adaptive Platform Functional Cluster (<code>ara::per</code>).\n</li><li>Kapselt Persistenzstrategien (Key-Value-Storage und File-Storage).\n</li><li>Bereitgestellte Schnittstelle: <code>ara::per::FileStorage::GetCurrentFileStorageSize()</code>.\n</li></ul>\n</li><li><strong><code>:Operating System</code> (Akteur / Lifeline):</strong>\n<ul class=\"fig-list\"><li>POSIX-konformes Betriebssystem (z. B. QNX Neutrino, Linux RT).\n</li><li>Verwaltet Virtual File System (VFS), Inodes und Blocktreiber.\n</li><li>Schnittstelle: Native OS-Systemaufrufe, im Diagramm als informativer Aufruf (<code>getSize()</code> mit Stereotyp <code>«aapInformative»</code>) abstrahiert.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Trigger:</strong> Die <code>:Adaptive Application</code> setzt den synchronen Aufruf <code>GetCurrentFileStorageSize()</code> auf einer geöffneten Instanz von <code>ara::per::FileStorage</code> ab.\n</li><li><strong>OS-Delegation:</strong> Der Cluster <code>:Persistency</code> initiiert intern den Aufruf <code>getSize()</code> an das <code>:Operating System</code>. Dies entspricht OS-seitig der Abfrage der physischen Dateigrößen bzw. Verzeichniseinträge (z. B. via <code>stat()</code> / <code>fstat()</code> / <code>statvfs()</code> oder Verzeichnistraversierung über <code>readdir()</code>).\n</li><li><strong>Ergebniserfassung &amp; Rückkehr:</strong>\n<ul class=\"fig-list\"><li>Das Betriebssystem liefert die File-Metadaten an <code>:Persistency</code> zurück.\n</li><li><code>:Persistency</code> aggregiert die Bytegrößen aller zugeordneten persistenten Dateien und terminiert die synchrone Ausführung mit Rückgabe des akkumulierten Werts als <code>ara::core::Result&lt;std::uint64_t&gt;</code>.\n</li><li>Tritt während des OS-Zugriffs ein Fehler auf (z. B. I/O-Fault, unvollständige Metadaten), bricht die Sequenz ab und transformiert den Fehler in einen <code>ara::per::PerErrc</code> (z. B. <code>kPhysicalStorageFailure</code>).\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>API-Vertrag (Applikationsebene):</strong>\n<ul class=\"fig-list\"><li>Aufruf ist blockierend/synchron. Entwickler dürfen <code>GetCurrentFileStorageSize()</code> nicht in zeitkritischen Thread-Kontexten oder harten Echtzeitschleifen ausführen, da je nach Dateianzahl und Storage-Typ signifikante I/O-Latenzen entstehen.\n</li><li>Der Rückgabewert ist typisiert als <code>ara::core::Result&lt;std::uint64_t&gt;</code> und erzwingt zwingend eine Fehlerbehandlung vor dem Dereferenzieren des Werts.\n</li></ul>\n</li><li><strong>Platform- &amp; Stack-Implementierung:</strong>\n<ul class=\"fig-list\"><li>Der Persistency-Stack muss sicherstellen, dass nur Dateien erfasst werden, die zum Namespace und Scope des jeweiligen <code>PersistencyFileStorage</code> gehören (Vermeidung von Information Leakage).\n</li><li>Zur Latenzoptimierung empfiehlt sich stack-intern ein aggregiertes Tracking bei Schreiboperationen oder Caching der Dateigrößen, um wiederholte Traversierungen des VFS zu minimieren.\n</li></ul>\n</li><li><strong>Konfigurationsbezug (Manifeste):</strong>\n<ul class=\"fig-list\"><li>Die ermittelte Größe korreliert direkt mit dem im Execution/Platform-Manifest definierten Parameter <code>PersistencyFileStorage.maximumAllowedSize</code>.\n</li><li>Dient typischerweise dem präventiven Quota-Monitoring der Applikation, bevor Schreiboperationen via <code>OpenFileWrite()</code> oder <code>Write()</code> mit Quota-Exceeded-Fehlern fehlschlagen.\n</li></ul>\n</li></ul>"}], "trans": [{"from": "FIG-6f257f695ecee51e", "to": "FIG-aa102024e40b7d7b", "fr": "R23-11", "tr": "R24-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Nachricht <code>getSize()</code> (<code>:Persistency</code> → <code>:Operating System</code>): Ergänzung des Stereotyps <code>«aapInformative»</code> unterhalb des Methodenaufrufs zur formalen Kennzeichnung als nicht-normative bzw. plattformspezifische Interaktion.\n</li></ul>"}]};
